    original_input: input,
    previous_context: previous,
    reviewed_context: reviewed
  }
}];

const llmResponse = $input.first().json;
const source = $('Build vLLM Chat Turn Parse Body').first().json;
const previous = source.previous_context || null;
const reviewed = source.reviewed_context || null;
const original = source.original_input || {};

let content = null;
if (llmResponse.choices?.[0]?.message?.content) {
  content = llmResponse.choices[0].message.content;
} else if (llmResponse.turn_type !== undefined) {
  content = llmResponse;
} else {
  content = llmResponse;
}

let parsed = {};
if (typeof content === "string") {
  try {
    parsed = JSON.parse(content);
  } catch (error) {
    parsed = {};
  }
} else if (typeof content === "object" && content !== null) {
  parsed = content;
}

const allowedTurns = ["SMALL_TALK", "CANCEL", "CONFUSED", "UNKNOWN", "TASK_REQUEST", "CLARIFICATION_VALUES", "APPROVAL_DECISION"];
const turnType = allowedTurns.includes(parsed.turn_type) ? parsed.turn_type : "UNKNOWN";
const previousContext = previous?.context || original.context || {};
const operatorId = parsed.operator_id || (turnType === "CLARIFICATION_VALUES" ? previous?.operator_id : null) || null;
const intentText = parsed.intent_text || previous?.intent_text || parsed.raw_chat_input || source.raw_chat_input || "";
const reason = parsed.reason || (turnType === "CLARIFICATION_VALUES" ? previous?.reason : null) || null;
const debug = parsed.debug === true || previous?.debug === true || original.debug === true;
const reviewedPatchExists = !!(reviewed && reviewed.status === "REVIEWED");

return [{
  json: {
    turn_type: turnType,
    operator_id: operatorId,
    intent_text: intentText,
    reason,
    decision: parsed.decision || null,
    comment: parsed.comment || null,
    raw_chat_input: parsed.raw_chat_input || source.raw_chat_input || "",
    debug,
    reviewed_patch_exists: reviewedPatchExists,
    reviewed_context: reviewed,
    confirmations: previous?.confirmations || original.confirmations || {},
    context: {
      ...previousContext,
      operator_id: operatorId || previousContext.operator_id || null,
      debug
    },
    body: {
      operator_id: operatorId,
      intent_text: intentText,
      reason
    },
    errors: []
  }
}];

const input = $input.first().json;
const reviewed = input.reviewed_context || {};
const candidatePatch = reviewed.payload?.candidate_patch || reviewed.body?.candidate_patch || null;
const affectedLines = reviewed.context?.affected_lines || reviewed.payload?.affected_lines || [];
const allowed = ["APPROVE", "REJECT", "REQUEST_REVISION"];
const decision = allowed.includes(input.decision) ? input.decision : "REQUEST_REVISION";
const comment = input.comment || input.raw_chat_input || "";
const operatorDecision = {
  decision,
  comment,
  raw_reply: input.raw_chat_input || null
};

return [{
  json: {
    ...reviewed,
    decision,
    comment,
    operator_decision: operatorDecision,
    context: { ...(reviewed.context || {}), affected_lines: affectedLines },
    body: {
      ...(reviewed.body || {}),
      candidate_patch: candidatePatch,
      affected_lines: affectedLines,
      decision,
      comment,
      operator_decision: operatorDecision,
      operator_id: reviewed.context?.operator_id || input.context?.operator_id || candidatePatch?.operator_id || 'operator_pending'
    },
    payload: {
      ...(reviewed.payload || {}),
      candidate_patch: candidatePatch,
      affected_lines: affectedLines,
      decision,
      comment,
      operator_decision: operatorDecision,
      raw_release_decision_reply: input.raw_chat_input || null
    }
  }
}];
